def normalize(language):
 code=str(language or '').lower().replace('_','-').split('-')[0]
 return code if code in LANGUAGES else 'en'

def preferred():
 return normalize(load().get('language') or locale.getlocale()[0] or 'en')

def translate(source,language='fr',**values):
 language=normalize(language)
 message=source if language=='fr' or source not in MESSAGES else MESSAGES[source][('en','es','de','it').index(language)]
 return message.format(**values) if values else message

def catalogue():
 return {lang:{key:translate(key,lang) for key in MESSAGES} for lang in LANGUAGES}
